// Geometry modifiers preserve original nodes; effects use the evaluated geometry.
export function localBox(o){const pts=samples({...o,subpaths:[]},32),xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);const x=Math.min(...xs),y=Math.min(...ys);return {x,y,w:Math.max(...xs)-x,h:Math.max(...ys)-y};}
export function warpPoint(o,p,reverse=false){const bend=o.modifiers?.find(m=>m.type==='bend'&&m.enabled!==false);if(!bend||!bend.amount)return {...p};const b=localBox(o),t=(p.x-b.x)/(b.w||1),dy=bend.amount*4*t*(1-t);return {x:p.x,y:p.y+(reverse?-dy:dy)};}
export function bendSlope(o,x){const bend=o.modifiers?.find(m=>m.type==='bend'&&m.enabled!==false);if(!bend?.amount)return 0;const b=localBox(o),t=(x-b.x)/(b.w||1);return bend.amount*4/(b.w||1)*(1-2*t);}
export function handlePoint(o,n,p,reverse=false){const warped=warpPoint(o,n),slope=bendSlope(o,n.x);return reverse?{x:p.x,y:n.y+p.y-warped.y-slope*(p.x-n.x)}:{x:p.x,y:warped.y+(p.y-n.y)+slope*(p.x-n.x)};}
export function evaluatedPath(o){o=evaluateCorners(o);if(o.component){const shape=componentShape(o.component);if(shape)o={...o,...shape};}if(!o.nodes)return o;const bend=o.modifiers?.find(m=>m.type==='bend'&&m.enabled!==false&&m.amount);if(!bend)return evaluateFall(o);const mapPath=path=>{const nodes=path.nodes.map(n=>{const p={...n,...warpPoint(o,n)};if(n.in)p.in=handlePoint(o,n,n.in);if(n.out)p.out=handlePoint(o,n,n.out);return p;});for(let i=0;i<nodes.length-(path.closed?0:1);i++){const a=nodes[i],b=nodes[(i+1)%nodes.length],rawA=path.nodes[i],rawB=path.nodes[(i+1)%nodes.length];if(!rawA.out&&!rawB.in){const dx=rawB.x-rawA.x,dy=rawB.y-rawA.y;a.out={x:a.x+dx/3,y:a.y+dy/3+bendSlope(o,rawA.x)*dx/3};b.in={x:b.x-dx/3,y:b.y-dy/3-bendSlope(o,rawB.x)*dx/3};}}return {...path,nodes};};return evaluateFall({...o,...mapPath(o),subpaths:(o.subpaths||[]).map(mapPath)});}
export function worldPath(o){const p=evaluatedPath(o),m=o.matrix||I();const map=n=>{const q={...n,...point(m,n)};if(n.in)q.in=point(m,n.in);if(n.out)q.out=point(m,n.out);return q;};return {...p,matrix:I(),nodes:p.nodes.map(map),subpaths:(p.subpaths||[]).map(c=>({...c,nodes:c.nodes.map(map)}))};}
export function migrateProject(input){assertJsonSafety(input);const p=clone(input);if(!p.schemaVersion||p.schemaVersion<2){p.schemaVersion=2;p.centerAxis=350;p.liveMirror=false;p.showAxis=true;for(const os of Object.values(p.views||{}))for(const o of os){if(o.type==='zipper'){o.teethSpacing??=o.teeth||3;o.openAmount??=0;o.teethWidth??=(o.zipWidth||7)/2;o.tapeWidth??=3;o.zipType??='jacket';}if(o.nodes)for(const n of o.nodes)n.nid??=uid();}}p.guides??={front:[],back:[]};for(const os of Object.values(p.views||{}))for(const o of os)if(o.nodes)for(const n of o.nodes)n.nid??=uid();return validateProject(p);}

const fallCache=new Map();
function evaluateFall(o){for(const m of o.modifiers?.filter(m=>m.type==='fabricFall'&&m.enabled!==false)||[])o=evaluateFallLayer(o,m);return o;}
function evaluateFallLayer(o,m){const cacheKey=JSON.stringify([o.nodes,o.closed,o.matrix,m]);if(fallCache.has(cacheKey))return {...o,nodes:fallCache.get(cacheKey)};const b=localBox(o),length=Math.max(1,Math.min(b.h,m.length??70)),start=b.y+b.h-length,intensity=Math.max(0,Math.min(25,m.intensity??5)),count=Math.max(1,Math.min(12,m.foldCount??3));const displacement=y=>{const t=Math.max(0,Math.min(1,(y-start)/length));return intensity*Math.sin(Math.PI*t)*(Math.sin(t*count*Math.PI*2)+(m.irregularity??.3)*Math.sin(t*17+(m.seed??1)));},regions=fallRegions(o,m),warp=p=>regions.length?fallWarp(p,regions,m):({...p,x:p.x+displacement(p.y)}),jac=(p,d)=>{const h=.001,a=warp({x:p.x-d.x*h,y:p.y-d.y*h}),z=warp({x:p.x+d.x*h,y:p.y+d.y*h});return {x:(z.x-a.x)/(2*h),y:(z.y-a.y)/(2*h)};};const derivative=(a,b,t)=>{const c=a.out||a,d=b.in||b,u=1-t;return {x:3*u*u*(c.x-a.x)+6*u*t*(d.x-c.x)+3*t*t*(b.x-d.x),y:3*u*u*(c.y-a.y)+6*u*t*(d.y-c.y)+3*t*t*(b.y-d.y)};};const nodes=[];let pendingIn=null;for(let i=0;i<o.nodes.length-(o.closed?0:1);i++){const a=o.nodes[i],z=o.nodes[(i+1)%o.nodes.length],affected=regions.length?[a,z,cubic(a,z,.25),cubic(a,z,.5),cubic(a,z,.75)].some(p=>{const q=warp(p);return Math.hypot(q.x-p.x,q.y-p.y)>.0001;}):Math.max(a.y,z.y,a.out?.y||a.y,z.in?.y||z.y)>start,steps=affected?Math.max(2,Math.ceil(Math.hypot(z.x-a.x,z.y-a.y)/Math.max(5,length/10))):1;for(let k=0;k<steps;k++){const t=k/steps,q=cubic(a,z,t),end=cubic(a,z,(k+1)/steps),d0=jac(q,derivative(a,z,t)),d1=jac(end,derivative(a,z,(k+1)/steps)),n={...a,...warp(q),nid:k?`${a.nid||i}:${k}/${steps}`:a.nid,edgeId:a.edgeId,edgeParents:a.edgeParents};delete n.in;delete n.out;if(pendingIn)n.in=pendingIn;n.out={x:n.x+d0.x/(steps*3),y:n.y+d0.y/(steps*3)};const target=warp(end);pendingIn={x:target.x-d1.x/(steps*3),y:target.y-d1.y/(steps*3)};nodes.push(n);}}if(o.closed&&nodes.length)nodes[0].in=pendingIn;else if(o.nodes.length){const last={...o.nodes.at(-1),...warp(o.nodes.at(-1))};if(pendingIn)last.in=pendingIn;delete last.out;nodes.push(last);}if(fallCache.size>120)fallCache.clear();fallCache.set(cacheKey,nodes);return {...o,nodes};}
